import{_ as e,o,c as r,a2 as a}from"./chunks/framework.BZO4qERu.js";const m=JSON.parse('{"title":"企业微信(WeCom / WeWork)","description":"","frontmatter":{},"headers":[],"relativePath":"zh/integrations/channels/wecom.md","filePath":"zh/integrations/channels/wecom.md","lastUpdated":1790952322000}'),n={name:"zh/integrations/channels/wecom.md"};function l(s,t,h,i,d,c){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="企业微信-wecom-wework" tabindex="-1">企业微信(WeCom / WeWork) <a class="header-anchor" href="#企业微信-wecom-wework" aria-label="Permalink to &quot;企业微信(WeCom / WeWork)&quot;">​</a></h1><p>把 Memoh Bot 接入企业微信,在组织的企微工作区内与用户私聊或在群聊中协作。</p><h2 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to &quot;前提条件&quot;">​</a></h2><ul><li>拥有 <a href="https://work.weixin.qq.com/" target="_blank" rel="noreferrer">企微管理后台</a> 的管理权限,用于创建 Bot 应用。</li></ul><h2 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to &quot;步骤&quot;">​</a></h2><h3 id="_1-在企微管理后台创建-bot" tabindex="-1">1. 在企微管理后台创建 Bot <a class="header-anchor" href="#_1-在企微管理后台创建-bot" aria-label="Permalink to &quot;1. 在企微管理后台创建 Bot&quot;">​</a></h3><p>在企微管理后台:</p><ol><li>登录 <a href="https://work.weixin.qq.com/" target="_blank" rel="noreferrer">企微管理后台</a>。</li><li>进入 <strong>应用管理</strong> 下的 <strong>自建应用</strong> 或 <strong>Bot 管理</strong>。</li><li>创建一个新的 Bot 应用。</li><li>记下 <strong>Bot ID</strong> 和 <strong>Secret</strong> 凭据。</li></ol><blockquote><p>官方文档:<a href="https://developer.work.weixin.qq.com/" target="_blank" rel="noreferrer">企微开放平台</a> · <a href="https://developer.work.weixin.qq.com/document/path/91770" target="_blank" rel="noreferrer">企微 Bot 文档</a></p></blockquote><h3 id="_2-在-memoh-里添加渠道" tabindex="-1">2. 在 Memoh 里添加渠道 <a class="header-anchor" href="#_2-在-memoh-里添加渠道" aria-label="Permalink to &quot;2. 在 Memoh 里添加渠道&quot;">​</a></h3><p>在 Memoh:</p><ol><li>打开 Bot 的 <strong>平台</strong> 标签页。</li><li>点 <strong>Add Channel</strong>,选择 <strong>WeCom</strong>。</li><li>填入 <strong>Bot ID</strong> 和 <strong>Secret</strong>;仅在需要时填自定义 <strong>WebSocket URL</strong>。</li><li>点 <strong>Save and Enable</strong>。</li></ol><p>启用后,Memoh 通过 WebSocket 连接企微并开始接收消息。</p><h2 id="凭据" tabindex="-1">凭据 <a class="header-anchor" href="#凭据" aria-label="Permalink to &quot;凭据&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><strong>Bot ID</strong></td><td>是</td><td>企微里该 Bot 的标识。</td></tr><tr><td><strong>Secret</strong></td><td>是</td><td>Bot 的鉴权凭据。</td></tr><tr><td><strong>WebSocket URL</strong></td><td>否</td><td>自定义 WebSocket 端点;留空时使用默认端点。</td></tr></tbody></table><h2 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to &quot;验证&quot;">​</a></h2><p>私聊给 Bot 发送 <code>/help</code>,或在群聊中 @Bot 并发送 <code>/help</code>。Bot 回复命令列表,说明渠道已接通。</p><h2 id="群聊" tabindex="-1">群聊 <a class="header-anchor" href="#群聊" aria-label="Permalink to &quot;群聊&quot;">​</a></h2><p>Bot 也能在企微群聊中使用:在群里 @Bot 即可触发回复。</p><h2 id="停用与更换凭据" tabindex="-1">停用与更换凭据 <a class="header-anchor" href="#停用与更换凭据" aria-label="Permalink to &quot;停用与更换凭据&quot;">​</a></h2><p>随时可在 Bot 的 <strong>平台</strong> 标签页停用或移除该渠道。更换凭据时,在同一面板更新 <strong>Bot ID</strong> / <strong>Secret</strong> 并保存即可。</p>',21)])])}const p=e(n,[["render",l]]);export{m as __pageData,p as default};
